<template>
  <ion-page>
    <ion-header class="ion-no-border"><ion-toolbar class="dashboard-toolbar"><div class="builder-header"><router-link to="/tourists" class="dashboard-brand"><span class="brand-mark">🌿</span><span>Lakbay<span class="brand-accent">Naujan</span><small>ITINERARY BUILDER</small></span></router-link><button class="checklist-trigger" type="button" aria-label="Open travel checklist" @click="checklistOpen = true">☑ <span>{{ items.length }}</span></button></div></ion-toolbar></ion-header>
    <ion-content>
      <main class="builder-shell">
        <div class="builder-heading"><div><p class="eyebrow">PLAN YOUR NEXT DISCOVERY</p><h1>Itinerary Builder</h1><p class="muted">Choose your destinations, set your route, and keep track of the places you visit.</p></div><button class="ui-button ui-button-secondary" @click="newItinerary">＋ New itinerary</button></div>
        <p v-if="message" class="feedback" :class="{ error: messageType === 'error' }" role="status">{{ message }}</p>
        <div class="builder-layout">
          <section class="explorer-panel">
            <div class="panel-heading"><div><p class="eyebrow">DISCOVER NAUJAN</p><h2>Tourist spot explorer</h2></div><span class="results-count">{{ filteredSpots.length }} places</span></div>
            <div class="filter-row"><label class="dashboard-search">⌕ <input v-model="search" type="search" placeholder="Search destinations" aria-label="Search destinations" /></label><label>Weather<select v-model="weather"><option>All Weather</option><option>Sunny</option><option>Cloudy</option><option>Rainy</option></select></label><label>Type<select v-model="category"><option>All Destinations</option><option v-for="value in categories" :key="value">{{ value }}</option></select></label></div>
            <div v-if="loading" class="dashboard-loading">Loading destinations…</div><div v-else-if="!filteredSpots.length" class="dashboard-empty"><h2>No destinations found</h2><p class="muted">Try another search or filter.</p></div>
            <div v-else class="spot-list"><article v-for="spot in filteredSpots" :key="spot.id" class="spot-item"><img :src="spot.image_url || spot.image_urls?.[0] || '/images/naujan-lake.jpg'" :alt="spot.name" /><div class="spot-copy"><div class="spot-meta"><span>{{ spot.category }}</span><span>{{ weatherLabel(spot) }}</span></div><h3>{{ spot.name }}</h3><p class="muted">📍 {{ spot.address }}</p><p>{{ spot.description }}</p><div class="spot-actions"><span v-if="average(spot.id)" class="rating">★ {{ average(spot.id) }}</span><button class="ui-button" :disabled="hasSpot(spot.id)" @click="addSpot(spot)">{{ hasSpot(spot.id) ? 'Added' : 'Add to itinerary' }}</button></div></div></article></div>
          </section>
          <aside class="itinerary-panel"><div class="panel-heading"><div><p class="eyebrow">MY BUCKET LIST</p><h2>My itinerary</h2></div><span class="progress-pill">{{ visitedCount }}/{{ items.length || 0 }}</span></div><input v-model="title" class="title-input" placeholder="Name your itinerary" aria-label="Itinerary title" /><div v-if="items.length" class="progress-track"><span :style="{ width: `${progress}%` }" /></div><p v-if="items.length" class="muted progress-text">{{ visitedCount }} of {{ items.length }} destinations visited · {{ progress }}%</p><div v-if="!items.length" class="empty-itinerary"><span>🧭</span><h3>Your route starts here</h3><p class="muted">Add destinations from the explorer to build your travel plan.</p></div><ol v-else class="itinerary-list"><li v-for="(item, index) in items" :key="item.spot_id" :class="{ visited: item.visited }"><button class="move-button" :disabled="index === 0" aria-label="Move destination up" @click="move(index, -1)">↑</button><input v-model="item.visited" type="checkbox" :aria-label="`Mark ${item.spot?.name} visited`" @change="markChanged" /><img :src="item.spot?.image_url || item.spot?.image_urls?.[0] || '/images/naujan-lake.jpg'" alt="" /><div><strong>{{ index + 1 }}. {{ item.spot?.name }}</strong><small>{{ item.spot?.address }}</small></div><button class="move-button" :disabled="index === items.length - 1" aria-label="Move destination down" @click="move(index, 1)">↓</button><button class="remove-button" :aria-label="`Remove ${item.spot?.name}`" @click="remove(index)">×</button></li></ol><div class="itinerary-actions"><button class="ui-button" :disabled="saving || !items.length" @click="save">{{ saving ? 'Saving…' : savedId ? 'Save changes' : 'Save itinerary' }}</button><button class="ui-button ui-button-secondary" :disabled="!items.length" @click="downloadItineraryPdf(currentItinerary, spots)">Download PDF</button><button v-if="items.length" class="clear-button" @click="clearItems">Clear itinerary</button></div><div v-if="itineraries.length" class="saved-itineraries"><label>Saved itineraries<select v-model="selectedId" @change="loadSelected"><option value="">Current itinerary</option><option v-for="saved in itineraries" :key="saved.id" :value="saved.id">{{ saved.title }}</option></select></label></div></aside>
        </div>
      </main>
    </ion-content>
    <ion-modal :is-open="checklistOpen" @did-dismiss="checklistOpen = false"><ion-header><ion-toolbar><ion-title>My Travel Checklist</ion-title><ion-buttons slot="end"><ion-button @click="checklistOpen = false">Close</ion-button></ion-buttons></ion-toolbar></ion-header><ion-content class="ion-padding"><div class="checklist-modal"><p class="eyebrow">{{ title || 'YOUR TRIP' }}</p><h2>{{ visitedCount }} of {{ items.length }} destinations visited — {{ progress }}% completed</h2><label v-for="item in items" :key="item.spot_id" class="check-row"><input v-model="item.visited" type="checkbox" @change="markChanged" /><span>{{ item.spot?.name }}</span></label><button class="ui-button" :disabled="saving" @click="save">Save itinerary</button><button class="ui-button ui-button-secondary" @click="downloadItineraryPdf(currentItinerary, spots)">Download PDF</button><button class="ui-button ui-button-secondary" @click="downloadMasterChecklist(spots)">Complete tourist spot checklist</button></div></ion-content></ion-modal>
    <ion-modal :is-open="reviewOpen" @did-dismiss="reviewOpen = false"><ion-header><ion-toolbar><ion-title>Share your experience</ion-title><ion-buttons slot="end"><ion-button @click="reviewOpen = false">Later</ion-button></ion-buttons></ion-toolbar></ion-header><ion-content class="ion-padding"><div class="review-modal"><p class="eyebrow">TRIP COMPLETE</p><h2>How was your experience?</h2><p class="muted">Your feedback helps future travelers discover the best of Naujan.</p><div v-for="spot in items.filter(item => item.visited)" :key="spot.spot_id" class="review-row"><strong>{{ spot.spot?.name }}</strong><div class="stars"><button v-for="star in 5" :key="star" type="button" :class="{ active: (draftReviews[spot.spot_id]?.rating || 0) >= star }" :aria-label="`${star} stars`" @click="setRating(spot.spot_id, star)">★</button></div><textarea v-model="reviewDraft(spot.spot_id).comment" rows="3" maxlength="2000" placeholder="Tell us about your visit (optional)" /><button class="ui-button" :disabled="reviewSaving === spot.spot_id || !draftReviews[spot.spot_id]?.rating" @click="submitReview(spot.spot_id)">{{ reviewSaving === spot.spot_id ? 'Submitting…' : 'Submit review' }}</button></div></div></ion-content></ion-modal>
  </ion-page>
</template>
<script setup lang="ts">
import { computed, ref } from 'vue';
import { IonPage, IonHeader, IonToolbar, IonContent, IonModal, IonTitle, IonButtons, IonButton, onIonViewWillEnter } from '@ionic/vue';
import { supabase } from '../lib/supabase';
import type { TouristSpot } from '../lib/types';
import { downloadItineraryPdf, downloadMasterChecklist, loadItineraries, saveItinerary, saveReview, type Itinerary, type ItineraryItem } from '../lib/itinerary';
import { errorMessage } from '../lib/errors';
const spots = ref<TouristSpot[]>([]); const items = ref<ItineraryItem[]>([]); const itineraries = ref<Itinerary[]>([]); const savedId = ref(''); const selectedId = ref(''); const title = ref('My Naujan adventure'); const search = ref(''); const category = ref('All Destinations'); const weather = ref('All Weather'); const loading = ref(true); const saving = ref(false); const checklistOpen = ref(false); const reviewOpen = ref(false); const message = ref(''); const messageType = ref('success'); const userId = ref(''); const draftReviews = ref<Record<string, { rating: number; comment: string }>>({}); const reviewSaving = ref(''); const ratingMap = ref<Record<string, number[]>>({});
const categories = computed(() => [...new Set(spots.value.map(spot => spot.category))].sort());
const filteredSpots = computed(() => spots.value.filter(spot => `${spot.name} ${spot.address} ${spot.description}`.toLowerCase().includes(search.value.toLowerCase().trim()) && (category.value === 'All Destinations' || spot.category === category.value) && (weather.value === 'All Weather' || spot.weather_suitability?.includes(weather.value) || (!spot.weather_suitability?.length && weather.value === 'Sunny'))));
const visitedCount = computed(() => items.value.filter(item => item.visited).length); const progress = computed(() => items.value.length ? Math.round(visitedCount.value / items.value.length * 100) : 0); const currentItinerary = computed<Itinerary>(() => ({ id: savedId.value, user_id: userId.value, title: title.value, status: progress.value === 100 && items.value.length ? 'completed' : progress.value ? 'in_progress' : 'planning', created_at: '', updated_at: '', items: items.value }));
const average = (id: string) => { const values = ratingMap.value[id] ?? []; return values.length ? (values.reduce((sum, value) => sum + value, 0) / values.length).toFixed(1) : ''; };
const hasSpot = (id: string) => items.value.some(item => item.spot_id === id); const weatherLabel = (spot: TouristSpot) => spot.weather_suitability?.join(' · ') || 'Weather suitability not set';
function addSpot(spot: TouristSpot) { if (!hasSpot(spot.id)) items.value.push({ spot_id: spot.id, position: items.value.length, visited: false, spot }); }
function remove(index: number) { items.value.splice(index, 1); normalize(); }
function move(index: number, direction: number) { const next = index + direction; if (next < 0 || next >= items.value.length) return; [items.value[index], items.value[next]] = [items.value[next], items.value[index]]; normalize(); }
function normalize() { items.value.forEach((item, position) => { item.position = position; }); }
function markChanged() { normalize(); }
function clearItems() { if (window.confirm('Clear this itinerary? Your saved itinerary will remain until you save the empty list.')) { items.value = []; savedId.value = ''; selectedId.value = ''; } }
function newItinerary() { title.value = 'My Naujan adventure'; items.value = []; savedId.value = ''; selectedId.value = ''; message.value = ''; }
async function save() { if (!userId.value || !items.value.length) return; saving.value = true; try { savedId.value = await saveItinerary(userId.value, savedId.value ? { id: savedId.value, title: title.value, status: currentItinerary.value.status } : null, items.value); messageType.value = 'success'; message.value = 'Itinerary saved.'; await loadSaved(); if (progress.value === 100 && !localStorage.getItem(`lakbay-review-prompted-${savedId.value}`)) { reviewOpen.value = true; localStorage.setItem(`lakbay-review-prompted-${savedId.value}`, '1'); } } catch (e) { messageType.value = 'error'; message.value = errorMessage(e, 'Could not save itinerary.'); } finally { saving.value = false; } }
async function loadSaved() { if (!userId.value) return; itineraries.value = await loadItineraries(userId.value); }
function loadSelected() { const selected = itineraries.value.find(value => value.id === selectedId.value); if (!selected) return; savedId.value = selected.id; title.value = selected.title; items.value = selected.items; }
function reviewDraft(id: string) { if (!draftReviews.value[id]) draftReviews.value[id] = { rating: 0, comment: '' }; return draftReviews.value[id]; }
function setRating(id: string, rating: number) { reviewDraft(id).rating = rating; }
async function submitReview(id: string) { const draft = draftReviews.value[id]; if (!draft) return; reviewSaving.value = id; try { await saveReview(userId.value, savedId.value, id, draft.rating, draft.comment); message.value = 'Review submitted. Thank you!'; } catch (e) { messageType.value = 'error'; message.value = errorMessage(e, 'Could not submit review.'); } finally { reviewSaving.value = ''; } }
async function load() { loading.value = true; try { const auth = await supabase.auth.getUser(); if (!auth.data.user) return; userId.value = auth.data.user.id; const result = await supabase.from('tourist_spots').select('*').order('name'); if (result.error) throw result.error; spots.value = (result.data ?? []) as TouristSpot[]; const reviewResult = await supabase.from('reviews').select('tourist_spot_id, rating'); if (!reviewResult.error) { ratingMap.value = (reviewResult.data ?? []).reduce((map, review) => { (map[review.tourist_spot_id] ??= []).push(review.rating); return map; }, {} as Record<string, number[]>); } await loadSaved(); } catch (e) { messageType.value = 'error'; message.value = errorMessage(e, 'Could not load itinerary builder.'); } finally { loading.value = false; } }
onIonViewWillEnter(load);
</script>
<style scoped>
