p-soft);color:var(--app-accent);border-radius:20px;padding:7px 12px;font-weight:800}.title-input{margin:18px 0;font-size:14px}.progress-track{height:8px;background:var(--app-soft);border-radius:10px;overflow:hidden}.progress-track span{display:block;height:100%;background:var(--app-accent);transition:width .2s}.progress-text{font-size:12px}.empty-itinerary{text-align:center;padding:35px 14px}.empty-itinerary span{font-size:40px}.itinerary-list{padding:0;margin:16px 0;display:grid;gap:8px}.itinerary-list li{list-style:none;display:grid;grid-template-columns:22px 18px 42px 1fr 22px 22px;align-items:center;gap:7px;border:1px solid var(--app-border);border-radius:12px;padding:8px}.itinerary-list li.visited{opacity:.65;background:var(--app-soft)}.itinerary-list img{width:42px;height:42px;border-radius:8px;object-fit:cover}.itinerary-list strong,.itinerary-list small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.itinerary-list small{font-size:10px;color:var(--app-muted);margin-top:3px}.move-button,.remove-button,.clear-button{border:0;background:transparent;cursor:pointer;color:var(--app-accent);font-weight:800}.move-button:disabled{opacity:.25}.remove-button{font-size:20px;color:var(--app-error-text)}.itinerary-actions{display:grid;gap:8px}.clear-button{font-size:12px}.saved-itineraries{border-top:1px solid var(--app-border);padding-top:14px;margin-top:14px}.checklist-modal,.review-modal{max-width:540px;margin:auto;display:grid;gap:12px}.checklist-modal h2,.review-modal h2{color:var(--app-heading)}.check-row{display:flex;align-items:center;gap:10px;padding:12px;border:1px solid var(--app-border);border-radius:10px}.review-row{border-top:1px solid var(--app-border);padding-top:16px;display:grid;gap:8px}.stars button{border:0;background:transparent;color:#c8d1ca;font-size:28px;cursor:pointer;padding:0 2px}.stars button.active{color:#c78919}.review-row textarea{width:100%;border:1px solid var(--app-border);border-radius:10px;padding:10px;font:inherit;resize:vertical}
@media(max-width:850px){.builder-layout{grid-template-columns:1fr}.itinerary-panel{position:static}.filter-row{grid-template-columns:1fr 1fr}.filter-row .dashboard-search{grid-column:1/-1}}
@media(max-width:560px){.builder-shell{padding:20px 14px 35px}.builder-header{padding:8px 14px}.builder-heading{align-items:flex-start;flex-direction:column}.spot-item{grid-template-columns:95px 1fr}.spot-item img{width:95px;min-height:180px}.spot-copy{padding:10px 10px 10px 0}.spot-copy p{display:none}.spot-actions{align-items:flex-end;gap:5px;flex-direction:column}.filter-row{grid-template-columns:1fr}.filter-row .dashboard-search{grid-column:auto}.itinerary-list li{grid-template-columns:18px 18px 38px 1fr 18px 18px;gap:4px}}
